-- Synthetic local test fixture only. Never apply to a real project.
CREATE TABLE public.camera_integrations(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,provider text NOT NULL UNIQUE,
 server_host text NOT NULL,server_port integer,enabled boolean NOT NULL DEFAULT false,
 username_secret_id uuid,password_secret_id uuid,webhook_secret_id uuid,
 last_sync_at timestamptz,last_sync_status text,last_error text,metadata jsonb NOT NULL DEFAULT '{}',
 created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
 ALTER TABLE public.camera_integrations ENABLE ROW LEVEL SECURITY;
 GRANT ALL ON public.camera_integrations TO service_role;
 GRANT USAGE,SELECT ON SEQUENCE public.camera_integrations_id_seq TO service_role;
 CREATE SCHEMA extensions;
 -- Deterministic dummy bytes implement only the old Vault routine's fixture dependency.
 CREATE FUNCTION extensions.gen_random_bytes(integer) RETURNS bytea LANGUAGE SQL AS $$SELECT decode(repeat('00',$1),'hex')$$;
 CREATE SCHEMA vault;
 CREATE TABLE vault.secrets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),secret text,name text UNIQUE,description text);
 CREATE VIEW vault.decrypted_secrets AS SELECT id,secret AS decrypted_secret FROM vault.secrets;
 CREATE TABLE vault.synthetic_faults(fail_name text);
 INSERT INTO vault.synthetic_faults VALUES(NULL);
 CREATE TABLE vault.synthetic_updates(id uuid,secret text);
 CREATE FUNCTION vault.create_secret(secret text,name text,description text) RETURNS uuid LANGUAGE plpgsql AS $$
 DECLARE result uuid;BEGIN
 IF $2=(SELECT fail_name FROM vault.synthetic_faults) THEN RAISE EXCEPTION 'Synthetic Vault create failure';END IF;
 INSERT INTO vault.secrets(secret,name,description) VALUES($1,$2,$3) RETURNING id INTO result;RETURN result;END$$;
 CREATE FUNCTION vault.update_secret(secret_id uuid,new_secret text) RETURNS void LANGUAGE plpgsql AS $$BEGIN
 IF (SELECT name FROM vault.secrets WHERE id=$1)=(SELECT fail_name FROM vault.synthetic_faults) THEN
 RAISE EXCEPTION 'Synthetic Vault update failure';END IF;
 UPDATE vault.secrets SET secret=$2 WHERE id=$1;
 IF NOT FOUND THEN RAISE EXCEPTION 'Synthetic missing Vault reference';END IF;
 INSERT INTO vault.synthetic_updates VALUES($1,$2);END$$;
